import concurrent.futures
import urllib.request

URL = "http://127.0.0.1:18080"
KEY = "contended.bin"
PAYLOAD_A = b"A" * (512 * 1024)
PAYLOAD_B = b"B" * (512 * 1024)
VALID = {PAYLOAD_A, PAYLOAD_B}

def put(payload):
    req = urllib.request.Request(f"{URL}/blobs/{KEY}", data=payload, method="PUT")
    with urllib.request.urlopen(req, timeout=5) as resp:
        return resp.status

def get():
    try:
        with urllib.request.urlopen(f"{URL}/blobs/{KEY}", timeout=5) as resp:
            return resp.status, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, b""

results = {"errors": [], "bodies": []}

def writer(payload, n):
    for _ in range(15):
        status = put(payload)
        if status != 201:
            results["errors"].append(("put", status))

def reader(n):
    for _ in range(60):
        status, body = get()
        if status == 200:
            results["bodies"].append(body)
        elif status != 404:
            results["errors"].append(("get", status))

with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:
    futs = [
        ex.submit(writer, PAYLOAD_A, 0),
        ex.submit(writer, PAYLOAD_B, 0),
        ex.submit(reader, 0),
    ]
    for f in futs:
        f.result()

print("errors:", results["errors"])
print("bodies observed:", len(results["bodies"]))
bad = [b for b in results["bodies"] if b not in VALID]
print("corrupted bodies:", len(bad))
assert not results["errors"]
assert not bad
print("OK: no torn reads over real HTTP")
